CREATE TYPE subscription_status AS ENUM ('trialing', 'active', 'past_due', 'canceled');
CREATE TYPE operation_job_type AS ENUM ('translation', 'render');
CREATE TYPE operation_job_status AS ENUM ('queued', 'processing', 'completed', 'failed', 'canceled');
CREATE TABLE subscriptions (organization_id UUID PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, plan_code TEXT NOT NULL, status subscription_status NOT NULL, provider TEXT, provider_customer_id TEXT, provider_subscription_id TEXT, current_period_end TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX subscriptions_provider_id_idx ON subscriptions (provider, provider_subscription_id) WHERE provider_subscription_id IS NOT NULL;
CREATE TABLE usage_events (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, metric TEXT NOT NULL, quantity BIGINT NOT NULL CHECK (quantity > 0), idempotency_key TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (organization_id, idempotency_key));
CREATE INDEX usage_events_tenant_time_idx ON usage_events (organization_id, occurred_at DESC);
CREATE TABLE notifications (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX notifications_user_unread_idx ON notifications (user_id, created_at DESC) WHERE read_at IS NULL;
CREATE TABLE operation_jobs (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, requested_by_user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT, asset_id UUID REFERENCES assets(id) ON DELETE CASCADE, job_type operation_job_type NOT NULL, status operation_job_status NOT NULL DEFAULT 'queued', input JSONB NOT NULL, output JSONB, idempotency_key TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, available_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (organization_id, idempotency_key));
CREATE INDEX operation_jobs_claim_idx ON operation_jobs (job_type, status, available_at) WHERE status IN ('queued', 'failed');
CREATE INDEX operation_jobs_tenant_created_idx ON operation_jobs (organization_id, created_at DESC);
